input.newString:
from storage import save_todos


def add_todo(todos, item, path=None):
    if not item:
        raise ValueError("item cannot be empty")
    todos.append({"text": item, "done": False})
    if path is not None:
        save_todos(todos, path)
    return todos


def complete_todo(todos, index, path=None):
    if index < 0 or index >= len(todos):
        raise IndexError("todo index out of range")
    todos[index]["done"] = True
    if path is not None:
        save_todos(todos, path)
    return todos
